struct VSOut {
    float4 pos : SV_POSITION;
};

VSOut VSMain(uint vid : SV_VertexID)
{
    VSOut o;
    float2 tri[3] = {
        float2(0.0f, -0.5f),
        float2(0.5f, 0.5f),
        float2(-0.5f, 0.5f)
    };
    o.pos = float4(tri[vid], 0.0f, 1.0f);
    return o;
}

cbuffer Host : register(b0)
{
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
};
struct VSOut { float4 pos : SV_POSITION; };
float4 PSMain(VSOut i) : SV_Target
{
    float2 p = i.pos.xy / float2(resolution_x, resolution_y);
    p.y = 1.0f - p.y;
    return float4(p.x, p.y * 0.7f + 0.2f, 0.15f, 1.0f);
}
